import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { CheckCircleIcon, ExclamationTriangleIcon, InformationCircleIcon } from '@heroicons/react/24/outline';
import { useNotification } from '../hooks/useNotification';
import { wizardAPI } from '../services/api';
import DNSVerificationStep from './wizard/DNSVerificationStep';
import SPFConfigurationStep from './wizard/SPFConfigurationStep';
import DKIMConfigurationStep from './wizard/DKIMConfigurationStep';
import DMARCConfigurationStep from './wizard/DMARCConfigurationStep';
import AlertConfigurationStep from './wizard/AlertConfigurationStep';
import SummaryStep from './wizard/SummaryStep';

const ConfigurationWizard = ({ domainId, onComplete }) => {
  const [currentStep, setCurrentStep] = useState(1);
  const [wizardData, setWizardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [stepData, setStepData] = useState({});
  const { showNotification } = useNotification();
  const navigate = useNavigate();

  const steps = [
    {
      id: 1,
      title: 'Verificación DNS',
      description: 'Verificar registros DNS existentes',
      component: 'DNSVerificationStep'
    },
    {
      id: 2,
      title: 'Configuración SPF',
      description: 'Configurar registro SPF',
      component: 'SPFConfigurationStep'
    },
    {
      id: 3,
      title: 'Configuración DKIM',
      description: 'Configurar registro DKIM',
      component: 'DKIMConfigurationStep'
    },
    {
      id: 4,
      title: 'Configuración DMARC',
      description: 'Configurar política DMARC',
      component: 'DMARCConfigurationStep'
    },
    {
      id: 5,
      title: 'Configuración de Alertas',
      description: 'Configurar notificaciones y alertas',
      component: 'AlertConfigurationStep'
    },
    {
      id: 6,
      title: 'Resumen',
      description: 'Revisar configuración final',
      component: 'SummaryStep'
    }
  ];

  useEffect(() => {
    loadWizardData();
  }, [domainId]);

  const loadWizardData = async () => {
    try {
      setLoading(true);
      const response = await wizardAPI.getProgress(domainId);
      setWizardData(response.data);
      setCurrentStep(response.data.current_step || 1);
      setStepData(response.data.step_data || {});
    } catch (error) {
      console.error('Error loading wizard data:', error);
      showNotification('Error al cargar el asistente de configuración', 'error');
    } finally {
      setLoading(false);
    }
  };

  const saveStepData = async (step, data) => {
    try {
      setSaving(true);
      await wizardAPI.saveStep(domainId, step, data);
      setStepData(prev => ({ ...prev, [step]: data }));
      showNotification('Paso guardado correctamente', 'success');
    } catch (error) {
      console.error('Error saving step data:', error);
      showNotification('Error al guardar el paso', 'error');
      throw error;
    } finally {
      setSaving(false);
    }
  };

  const nextStep = async (data) => {
    try {
      await saveStepData(currentStep, data);

      if (currentStep < steps.length) {
        setCurrentStep(currentStep + 1);
        await wizardAPI.updateProgress(domainId, currentStep + 1);
      } else {
        // Completar wizard
        await wizardAPI.complete(domainId);
        showNotification('Configuración completada exitosamente', 'success');
        if (onComplete) {
          onComplete();
        } else {
          navigate('/domains');
        }
      }
    } catch (error) {
      console.error('Error proceeding to next step:', error);
    }
  };

  const prevStep = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const goToStep = (step) => {
    if (step <= currentStep) {
      setCurrentStep(step);
    }
  };

  const resetWizard = async () => {
    try {
      await wizardAPI.reset(domainId);
      setCurrentStep(1);
      setStepData({});
      showNotification('Asistente reiniciado', 'info');
    } catch (error) {
      console.error('Error resetting wizard:', error);
      showNotification('Error al reiniciar el asistente', 'error');
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  const currentStepData = steps.find(step => step.id === currentStep);

  return (
    <div className="max-w-4xl mx-auto">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-gray-900 mb-2">
          Asistente de Configuración DMARC
        </h1>
        <p className="text-gray-600">
          Te guiaremos paso a paso para configurar DMARC correctamente en tu dominio.
        </p>
      </div>

      {/* Progress Bar */}
      <div className="mb-8">
        <div className="flex items-center justify-between mb-4">
          {steps.map((step, index) => (
            <div key={step.id} className="flex items-center">
              <button
                onClick={() => goToStep(step.id)}
                disabled={step.id > currentStep}
                className={`
                  flex items-center justify-center w-10 h-10 rounded-full border-2 transition-colors
                  ${
                    step.id < currentStep
                      ? 'bg-green-500 border-green-500 text-white cursor-pointer'
                      : step.id === currentStep
                      ? 'bg-primary-600 border-primary-600 text-white'
                      : 'bg-gray-100 border-gray-300 text-gray-400 cursor-not-allowed'
                  }
                `}
              >
                {step.id < currentStep ? (
                  <CheckCircleIcon className="w-6 h-6" />
                ) : (
                  <span className="text-sm font-medium">{step.id}</span>
                )}
              </button>
              {index < steps.length - 1 && (
                <div
                  className={`
                    w-16 h-0.5 mx-2
                    ${step.id < currentStep ? 'bg-green-500' : 'bg-gray-300'}
                  `}
                />
              )}
            </div>
          ))}
        </div>

        <div className="text-center">
          <h3 className="text-lg font-medium text-gray-900">
            Paso {currentStep}: {currentStepData?.title}
          </h3>
          <p className="text-sm text-gray-600 mt-1">
            {currentStepData?.description}
          </p>
        </div>
      </div>

      {/* Step Content */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 mb-6">
        <StepContent
          step={currentStep}
          domainId={domainId}
          data={stepData[currentStep] || {}}
          onNext={nextStep}
          onPrev={prevStep}
          canGoBack={currentStep > 1}
          canGoNext={currentStep < steps.length}
          saving={saving}
        />
      </div>

      {/* Actions */}
      <div className="flex justify-between items-center">
        <button
          onClick={resetWizard}
          className="text-sm text-gray-500 hover:text-gray-700 transition-colors"
        >
          Reiniciar asistente
        </button>

        <div className="text-sm text-gray-500">
          Paso {currentStep} de {steps.length}
        </div>
      </div>
    </div>
  );
};

// Componente para renderizar el contenido de cada paso
const StepContent = ({ step, domainId, data, onNext, onPrev, canGoBack, canGoNext, saving }) => {
  const [stepData, setStepData] = useState(data);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    setStepData(data);
  }, [data]);

  const handleNext = () => {
    // Validar datos del paso actual
    const validation = validateStep(step, stepData);
    if (validation.isValid) {
      onNext(stepData);
    } else {
      setErrors(validation.errors);
    }
  };

  const updateStepData = (key, value) => {
    setStepData(prev => ({ ...prev, [key]: value }));
    // Limpiar errores cuando el usuario modifica los datos
    if (errors[key]) {
      setErrors(prev => ({ ...prev, [key]: null }));
    }
  };

  // Renderizar contenido específico según el paso
  switch (step) {
    case 1:
      return (
        <DNSVerificationStep
          domainId={domainId}
          data={stepData}
          onChange={updateStepData}
          errors={errors}
          onNext={handleNext}
          onPrev={onPrev}
          canGoBack={canGoBack}
          saving={saving}
        />
      );
    case 2:
      return (
        <SPFConfigurationStep
          domainId={domainId}
          data={stepData}
          onChange={updateStepData}
          errors={errors}
          onNext={handleNext}
          onPrev={onPrev}
          canGoBack={canGoBack}
          saving={saving}
        />
      );
    case 3:
      return (
        <DKIMConfigurationStep
          domainId={domainId}
          data={stepData}
          onChange={updateStepData}
          errors={errors}
          onNext={handleNext}
          onPrev={onPrev}
          canGoBack={canGoBack}
          saving={saving}
        />
      );
    case 4:
      return (
        <DMARCConfigurationStep
          domainId={domainId}
          data={stepData}
          onChange={updateStepData}
          errors={errors}
          onNext={handleNext}
          onPrev={onPrev}
          canGoBack={canGoBack}
          saving={saving}
        />
      );
    case 5:
      return (
        <AlertConfigurationStep
          domainId={domainId}
          data={stepData}
          onChange={updateStepData}
          errors={errors}
          onNext={handleNext}
          onPrev={onPrev}
          canGoBack={canGoBack}
          saving={saving}
        />
      );
    case 6:
      return (
        <SummaryStep
          domainId={domainId}
          data={stepData}
          onChange={updateStepData}
          errors={errors}
          onNext={handleNext}
          onPrev={onPrev}
          canGoBack={canGoBack}
          saving={saving}
        />
      );
    default:
      return <div>Paso no encontrado</div>;
  }
};

// Función de validación para cada paso
const validateStep = (step, data) => {
  const errors = {};
  let isValid = true;

  switch (step) {
    case 1:
      // Validación para verificación DNS
      if (!data.dnsVerified) {
        errors.dnsVerified = 'Debe completar la verificación DNS';
        isValid = false;
      }
      break;
    case 2:
      // Validación para configuración SPF
      if (!data.spfRecord) {
        errors.spfRecord = 'Debe configurar el registro SPF';
        isValid = false;
      }
      break;
    case 3:
      // Validación para configuración DKIM
      if (!data.dkimSelector) {
        errors.dkimSelector = 'Debe especificar el selector DKIM';
        isValid = false;
      }
      break;
    case 4:
      // Validación para configuración DMARC
      if (!data.dmarcPolicy) {
        errors.dmarcPolicy = 'Debe seleccionar una política DMARC';
        isValid = false;
      }
      break;
    case 5:
      // Validación para configuración de alertas
      if (data.enableAlerts && !data.alertEmail) {
        errors.alertEmail = 'Debe especificar un email para las alertas';
        isValid = false;
      }
      break;
  }

  return { isValid, errors };
};



export default ConfigurationWizard;
